nft.nat4:
ip
chain prerouting {
  type nat hook prerouting priority dstnat; policy accept;
  iifname "wan0.31" tcp dport { 80, 443 } dnat to 10.72.72.2
}
chain postrouting {
  type nat hook postrouting priority srcnat; policy accept;

  # Internet-bound only; our other networks (trusted.v4) are routed, not NATed.
  oifname "wan0.31" ip saddr 10.72.0.0/16 ip daddr != { 10.0.0.0/8 } masquerade
}

radvd:
interface lan0 {
  AdvSendAdvert on;
  MinRtrAdvInterval 200;
  MaxRtrAdvInterval 300;
  AdvLinkMTU 1500;
  AdvCurHopLimit 64;
  AdvManagedFlag on;
  AdvOtherConfigFlag on;
  RemoveAdvOnExit on;
  prefix 2001:db8:72:1::/64 {
    DeprecatePrefix on;
    AdvOnLink on;
    AdvAutonomous off;
  };
  RDNSS 2001:db8:72:1::1 {
  };
  DNSSL home.example.org {
  };
};
